def split_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [raw]
	out = []
	for item in raw or []:
		parts = []
		for part in str(item).split("|"):
			parts.append(part.strip())
		if parts and parts[0]:
			out.append(parts)
	return out


def num(value):
	try:
		text = str(value).replace(",", "").replace("$", "").replace("%", "").strip()
		if not text:
			return None
		return float(text)
	except Exception:
		return None


def money(value, cur):
	digits = str(int(round(value)))
	out = ""
	while len(digits) > 3:
		out = "," + digits[-3:] + out
		digits = digits[:-3]
	return cur + digits + out


def slugify(text):
	out = ""
	for ch in str(text or "").lower():
		out = out + (ch if ch.isalnum() else "-")
	return out


def fixed(value):
	return str(round(value, 2))

def axis_ticks(lo, hi):
	if lo is None or lo <= 0:
		lo = 1.0
	if hi is None or hi <= lo:
		hi = lo * 10
	ticks = [lo]
	power = 1.0
	while power * 10 <= lo:
		power = power * 10
	while power > lo:
		power = power / 10
	done = False
	guard = 0
	while not done and guard < 40:
		for mult in [1, 2.5, 5]:
			value = mult * power
			if value >= hi:
				done = True
				break
			if value > lo:
				ticks.append(value)
		power = power * 10
		guard = guard + 1
	ticks.append(hi)
	return ticks


def axis_pos(value, ticks):
	n = len(ticks)
	if n < 2 or value <= ticks[0]:
		return 0.0
	if value >= ticks[n - 1]:
		return 100.0
	i = 0
	while i < n - 2 and value > ticks[i + 1]:
		i = i + 1
	frac = (value - ticks[i]) / (ticks[i + 1] - ticks[i])
	return (i + frac) / (n - 1) * 100.0


def tick_label(value, cur):
	if value >= 1000000:
		x = value / 1000000.0
		suffix = "M"
	elif value >= 1000:
		x = value / 1000.0
		suffix = "K"
	else:
		x = value
		suffix = ""
	if x == int(x):
		shown = str(int(x))
	else:
		shown = str(round(x, 1))
	return cur + shown + suffix


def tape_ticks(ticks, cur, tick_label):
	out = []
	n = len(ticks)
	for i in range(n):
		x = 0.0 if n < 2 else i * 100.0 / (n - 1)
		edge = "mid"
		if i == 0:
			edge = "start"
		if i == n - 1:
			edge = "end"
		crowded = "true" if (n > 4 and (i == 1 or i == n - 2)) else "false"
		out.append({"x": str(round(x, 4)) + "%", "label": tick_label(ticks[i], cur), "major": "true", "edge": edge, "crowded": crowded})
		if i < n - 1:
			out.append({"x": str(round((i + 0.5) * 100.0 / (n - 1), 4)) + "%", "label": "", "major": "false", "edge": "mid", "crowded": "true"})
	return out


def axis_marks(ticks, cur, tick_label):
	out = []
	n = len(ticks)
	for i in range(n):
		edge = "mid"
		if i == 0:
			edge = "start"
		if i == n - 1:
			edge = "end"
		out.append({
			"x": str(round(0.0 if n < 2 else i * 100.0 / (n - 1), 4)) + "%",
			"label": tick_label(ticks[i], cur),
			"edge": edge,
			"crowded": "true" if (n > 4 and (i == 1 or i == n - 2)) else "false",
		})
	return out

cur = str(props.get("currency") or "$")
usual = str(props.get("usual_label") or "Usually")
ticks = axis_ticks(num(props.get("axis_min")), num(props.get("axis_max")))
jobs = []
for parts in split_rows(props.get("jobs")):
	if len(parts) < 5:
		continue
	low = num(parts[2])
	typical = num(parts[3])
	high = num(parts[4])
	if low is None or high is None:
		continue
	if high < low:
		swap = low
		low = high
		high = swap
	if typical is None or typical < low or typical > high:
		typical = (low + high) / 2
	incl = parts[5] if len(parts) > 5 else ""
	note = usual + " " + money(typical, cur) + "."
	if incl:
		note = note + " " + incl
	jobs.append({
		"chip": parts[0],
		"job": parts[1],
		"lo_txt": money(low, cur),
		"hi_txt": money(high, cur),
		"note": note,
		"lo": fixed(axis_pos(low, ticks)),
		"hi": fixed(axis_pos(high, ticks)),
		"typ": fixed(axis_pos(typical, ticks)),
		"pressed": "true" if len(jobs) == 0 else "false",
	})
first = {"job": "", "lo_txt": "", "hi_txt": "", "note": "", "lo": "0", "hi": "0", "typ": "0"}
if jobs:
	first = jobs[0]
component.jobs = jobs
component.job = first["job"]
component.lo_txt = first["lo_txt"]
component.hi_txt = first["hi_txt"]
component.note = first["note"]
component.lo = first["lo"]
component.hi = first["hi"]
component.typ = first["typ"]
component.ticks = tape_ticks(ticks, cur, tick_label)
component.tape_label = "Price tape from " + money(ticks[0], cur) + " to " + money(ticks[len(ticks) - 1], cur) + ", with the picked job's usual range marked"
component.component_data = {"jobs": jobs}
